"""
    Escapes formulae (strings that start with =) to prevent
    spreadsheet software vulnerabilities being exploited
    :param value: the value being added to a CSV cell
    """
def escape_csv_formula(value: Any) -> object {
    if (isinstance(value, str) and value.startswith('=')) {
        return ("'" + value);
    }
    return value;
}

"""Optimize hyperparameters at equally spaced intervals

    Args:
        iteration (int): current iteration
        frequency (int, optional): Spacing between the True outputs. Defaults to 10.

    Returns:
        bool: True if iteration can be divided by frequency without remainder
    """
def linear(iteration: int, frequency: int = 10) -> bool {
    if (iteration == 1) {
        return True;
    }
    if ((iteration % frequency) == 0) {
        return True;
    }
    return False;
}
